package net.officefloor.hq.app.claim;

import java.util.List;

/** amount is shown with two decimals; status is DRAFT, OPEN, SETTLED or VOID; number is "" when none;
 *  due is the due fixed when the claim was settled, else the figure its person's last statement bound
 *  it to, "" while it is live (or bound to n/a); openedBy is "" when never opened; stated is whether
 *  the last statement bound it; corrects is the number a correction corrects, "" for any other claim;
 *  roundingDate is the date its rounding goes by (a correction's: the date of the claim it corrects). */
public record ClaimResponse(String id, String personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String corrects,
        String roundingDate) {

    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(String.valueOf(claim.getId()), String.valueOf(claim.getPersonId()),
                claim.getAmount().setScale(2).toPlainString(), claim.getDate().toString(), claim.getNote(),
                claim.getStatus().name(), claim.getNumber() == null ? "" : claim.getNumber(),
                fixedDue(claim) == null ? "" : fixedDue(claim).setScale(2).toPlainString(),
                claim.getOpenedBy() == null ? "" : claim.getOpenedBy(), claim.isStated(),
                claim.getCorrects() == null ? "" : claim.getCorrects(),
                claim.getRoundingDate().toString());
    }

    /** The due a claim keeps whatever the rates do: fixed when settled, else bound by a statement. */
    public static java.math.BigDecimal fixedDue(Claim claim) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        return claim.isStated() ? claim.getStatedDue() : null;
    }

    public static List<ClaimResponse> from(List<Claim> claims) {
        return claims.stream().map(ClaimResponse::from).toList();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.rate.Rates;

/**
 * The late charge on a claim: an OPEN claim whose due-by (its date plus the sheet's terms) is before
 * the sheet's today gains the sheet's late percent of its figure for every full 30 days it is
 * overdue, rounded like due. A correction has no late charge. The charge is never bound by a statement; settling freezes it in.
 */
public final class LateCharge {

    public static final int PERIOD_DAYS = 30;

    private LateCharge() {
    }

    /** The charge on a claim's figure; zero when it is not overdue or has no figure. */
    public static BigDecimal of(Claim claim, BigDecimal figure, BigDecimal pct, int terms, LocalDate today,
            RoundingMode rounding) {
        if (figure == null || pct == null || pct.signum() == 0 || claim.getStatus() != ClaimStatus.OPEN
                || claim.isCorrection()) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.getDate().plusDays(terms), today);
        long periods = overdue > 0 ? overdue / PERIOD_DAYS : 0;
        return Rates.due(figure.multiply(BigDecimal.valueOf(periods)), pct, rounding);
    }

    /** The figure with its late charge added on top; null stays null. */
    public static BigDecimal withCharge(Claim claim, BigDecimal figure, BigDecimal pct, int terms, LocalDate today,
            RoundingMode rounding) {
        return figure == null ? null : figure.add(of(claim, figure, pct, terms, today, rounding));
    }
}
/**
 * Takes a statement: the person's due-total as the screen shows it now (the sum of their counting
 * claims' figures — fixed or at the rate in force on each claim's date, raised to the sheet's floor; n/a when their grade has no
 * rate today and no claim keeps a figure; an overdue claim's late charge included), and binds each
 * counting claim to its figure now — never its late charge, which keeps following the sheet's today.
 * A claim that does not count (a held person's OPEN claims included) is left unbound.
 */
public class TakeStatement {
    public void take(@Val Person person, Claims claims, Rates rates, Sheets sheets, People people,
            Settings settings, Out<Statement> statement) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        BigDecimal latePct = settings.latePct(sheetId);
        int terms = settings.terms(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        List<Claim> own = claims.ofPerson(sheetId, person.getId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        for (Claim claim : own) {
            if (!person.countsLive(claim)) {
                claim.setStated(false);
                claim.setStatedDue(null);
            } else {
                RoundingMode rounding = Rounding.of(claim, policyDate);
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                // A bound claim keeps its figure (even n/a); a live one is worked at the rate on its date.
                BigDecimal figure = fixed != null || claim.isStated() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor, rounding);
                anyFigure |= fixed != null;
                if (figure != null) {
                    anyFigure = true;
                    total = total.add(LateCharge.withCharge(claim, figure, latePct, terms, today, rounding));
                }
                claim.setStated(true);
                claim.setStatedDue(figure);
                counted++;
            }
            claims.bind(claim);
        }
        // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
        boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
        BigDecimal dueTotal = na ? null : total;
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statement.set(new Statement(dueTotal, counted));
    }
}
        BigDecimal latePct = settings.latePct(sheetId);
        int terms = settings.terms(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        List<Claim> all = claims.list(sheetId);
        Map<Long, RollupFigures.PersonFigures> byPerson = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean anyFigure = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsLive(claim)) {
                    continue;
                }
                claimed = claimed.add(claim.getAmount());
                RoundingMode rounding = Rounding.of(claim, policyDate);
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                anyFigure |= fixed != null;
                BigDecimal figure = fixed != null || claim.isStated() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor, rounding);
                if (figure != null) {
                    anyFigure = true;
                    due = due.add(LateCharge.withCharge(claim, figure, latePct, terms, today, rounding));
                }
            }
            // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
            boolean na = !anyFigure && rates.find(sheetId, person.getGrade(), today) == null;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            byPerson.put(person.getId(), new RollupFigures.PersonFigures(person.getName(),
                    show(claimed), na ? NA : show(due)));
        }
        return new RollupFigures(byPerson, show(claimedTotal), show(dueTotal));
    }

    /** Audit (on commit) the figures that moved since {@code before}, as taken by {@code user}. */
    public void recordChanges(String sheetId, String user, RollupFigures before) {
        RollupFigures after = figures(sheetId);
        int terms = settings.terms(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        for (Person person : people.list(sheetId)) {
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.countsLive(claim)
                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
                    continue;
                }
                RoundingMode rounding = Rounding.of(claim, policyDate);
                BigDecimal fixed = ClaimResponse.fixedDue(claim);
                BigDecimal figure = fixed != null || claim.isStated() ? fixed
                        : Rates.due(claim.getAmount(), rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), floor, rounding);
                if (figure != null) {
                    total = total.add(LateCharge.withCharge(claim, figure, latePct, terms, today, rounding));
                }
            }
        }
        periods.close(sheetId, name, total);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + request.user()
                + " period=" + name + " total=" + total.toPlainString());
        response.send(periods.list(sheetId));
    }
}
import { addDays } from '../claims/overdue';

// Due is worked in exact integers: an amount in cents times a rate in hundredths of a percent is
// due in millionths, then rounded to cents — half up for a claim dated before the sheet's policy date,
// half to even for one dated on or after it. No float ever touches it.

export const NA = 'n/a';

/** "10.25" -> 1025n. */
export function toCents(amount: string): bigint {
  const negative = amount.trim().startsWith('-');
  const [whole, frac = ''] = amount.trim().replace(/^[-+]/, '').split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** 1025n -> "10.25". */
export function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const frac = (abs % 100n).toString().padStart(2, '0');
  return `${negative ? '-' : ''}${abs / 100n}.${frac}`;
}

/** The due on an amount of cents at a rate ("12.50"), in cents, rounded half up or else half to
 *  even; null when there is no rate. */
export function dueCents(cents: bigint, rate: string | undefined, halfUp = false): bigint | null {
  if (rate === undefined) return null;
  const millionths = cents * toCents(rate);
  const negative = millionths < 0n;
  const abs = negative ? -millionths : millionths;
  const whole = abs / 10000n;
  const rest = abs % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
  return negative ? -rounded : rounded;
}

/** A due for display: two decimals, or n/a. */
export function showDue(due: bigint | null): string {
  return due === null ? NA : formatCents(due);
}

/** A live due raised to the sheet's floor ("1.00"); n/a stays n/a. */
export function floored(due: bigint | null, floor: string): bigint | null {
  if (due === null) return null;
  const min = toCents(floor);
  return due < min ? min : due;
}

/** What a late charge needs: the sheet's late percent ("10.00"), its terms in days and its today. */
export type Late = { pct: string; terms: number; today: string | undefined };

const DAY_MS = 86_400_000;

/** Whether a claim's live figures round half up: its rounding date (a correction's is the date of
 *  the claim it corrects) is before the sheet's policy date (blank: the sheet's today). */
export const roundsHalfUp = (claim: { roundingDate?: string; date: string }, policy: string | undefined) =>
  policy !== undefined && policy !== '' && (claim.roundingDate || claim.date) < policy;

/** A claim with a negative amount is a correction: its due has no floor and no late charge. */
export const isCorrection = (claim: { amount?: string }) => claim.amount !== undefined && toCents(claim.amount) < 0n;

/** The late charge on a figure in cents: an OPEN claim whose due-by (its date plus the terms) is
 *  before today gains the late percent of its figure for every full 30 days it is overdue, rounded
 *  like due. Never bound by a statement; settling freezes it into the settled due. */
export function lateCents(claim: { amount?: string; date: string; status?: string; roundingDate?: string }, figure: bigint, late: Late | undefined, policy?: string): bigint {
  if (late === undefined || late.today === undefined || claim.status !== 'OPEN' || isCorrection(claim)) return 0n;
  const dueBy = addDays(claim.date, late.terms);
  const days = Math.round((Date.parse(late.today) - Date.parse(dueBy)) / DAY_MS);
  const periods = days > 0 ? Math.floor(days / 30) : 0;
  return dueCents(figure * BigInt(periods), late.pct, roundsHalfUp(claim, policy)) ?? 0n;
}

/** A claim's due: the one fixed when it was settled or bound by a statement (a claim bound to n/a
 *  stays n/a), else its amount at the current rate, raised to the sheet's floor; an overdue claim's
 *  late charge is added on top. A correction is never floored and gains no late charge. Live figures
 *  round by the sheet's policy date (see roundsHalfUp). */
export function claimDue(
  claim: { amount: string; due: string; date: string; status?: string; stated?: boolean; roundingDate?: string },
  rate: string | undefined,
  floor: string,
  late?: Late,
  policy?: string,
): bigint | null {
  const live = dueCents(toCents(claim.amount), rate, roundsHalfUp(claim, policy));
  const figure = claim.due !== '' ? toCents(claim.due) : claim.stated ? null : isCorrection(claim) ? live : floored(live, floor);
  return figure === null ? null : figure + lateCents(claim, figure, late, policy);
}

/** A person's due-total: the sum of the figures of their claims that count. With no rate for their
 *  grade today it is n/a, unless a claim keeps a figure (a settled one, or one worked at the grade
 *  in force on its date); then it is the sum of the figures there are. A claim whose figure is n/a
 *  adds nothing. */
export function dueTotal(
  claims: { amount: string; due: string; date: string; status?: string; stated?: boolean; roundingDate?: string }[],
  rateOn: (date: string) => string | undefined,
  rateToday: string | undefined,
  floor: string,
  late?: Late,
  policy?: string,
): bigint | null {
  const figures = claims.map((c) => claimDue(c, rateOn(c.date), floor, late, policy));
  if (rateToday === undefined && figures.every((f) => f === null)) return null;
  return figures.reduce<bigint>((sum, f) => sum + (f ?? 0n), 0n);
}
import type { Claim } from './useClaims';

/** A date ("2026-03-01") moved on by a number of days, as YYYY-MM-DD. Worked in UTC so no time
 *  zone shifts it. */
export function addDays(date: string, days: number): string {
  const [y, m, d] = date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
}

/** A claim's due-by: its date plus the sheet's terms. */
export const dueBy = (c: Claim, terms: number) => addDays(c.date, terms);

/** A claim is overdue when it is OPEN and its due-by is before the sheet's today. */
export const isOverdue = (c: Claim, terms: number, today: string | undefined) =>
  c.status === 'OPEN' && today !== undefined && dueBy(c, terms) < today;

